def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    adv_gap = batch['advantage_gap']

    diff = ops.sub(lpw, lpl)
    weighted_diff = ops.mul(diff, adv_gap)
    loss_raw = ops.neg(ops.logsigmoid(weighted_diff))

    if weight is not None:
        loss_weighted = ops.mul(loss_raw, weight)
    else:
        loss_weighted = loss_raw

    return ops.sum(loss_weighted)

def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    adv = batch['advantage_gap']

    margin = ops.sub(lpl, lpw)  # positive margin means lower log_prob_w preferred
    loss_per_sample = ops.mul(ops.softplus(margin), adv)

    if weight is not None:
        loss_per_sample = ops.mul(loss_per_sample, weight)
    return ops.mean(loss_per_sample)

def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    delta_reg = batch['delta_regret']

    clipped_regret = ops.clamp(ops.neg(delta_reg), 0.0, 1e9)
    loss = ops.mul(ops.exp(clipped_regret), ops.sub(lpl, lpw))
    if weight is not None:
        loss = ops.mul(loss, weight)
    return ops.median(loss)
